import React, { useEffect, useState } from "react";

import useApi from "../../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import departmentsApi from "../../../../api/departmentsApi";
import { Loading } from "../../../../components";
import RadiologyPaymentsTable from "./RadiologyPaymentsTable";
import hospitalsApi from "../../../../api/hospitals/hospitalsApi";
import { useStateContext } from "../../../../contexts/ContextProvider";

const columns = [
  { name: "Title", uid: "laboratory_service_title" },
  { name: "Charge", uid: "charge" },
  { name: "Date", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function RadiologyOrdersList() {
  const [openInventoryFormModal, setopenInventoryFormModal] = useState(false);
  const navigate = useNavigate();
  const [selectedPhysiotherapyService, setselectedPhysiotherapyService] = useState();
  const [laboratoryOrders, setlaboratoryOrders] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);
  const {loggedInUser}= useStateContext()

  const laboratoryOrdersApi = useApi(hospitalsApi.hospitalStaffAction);





  const getlaboratoryOrders = async (data) => {

    await laboratoryOrdersApi.request({
      "action":"GetLaboratoryOrders",
      
  });
  };

  useEffect(() => {
    if (laboratoryOrdersApi.data) {
      if (laboratoryOrdersApi.data.length) {
        setlaboratoryOrders(laboratoryOrdersApi.data);
      }
    }
  }, [laboratoryOrdersApi.data]);

  useEffect(() => {

    getlaboratoryOrders();


  }, []);

  useEffect(() => {
    setdata(laboratoryOrders);
  }, [laboratoryOrders]);

  const handleEditAction = (item) => {
    setopenInventoryFormModal(true);
    setselectedPhysiotherapyService(item);
    setmodalTitle(`EDIT ${item.laboratory_service_title}`);
    setUpdated(false)
  };

  const handleAddAction = () => {
    setopenInventoryFormModal(true);
    setmodalTitle("Add new pathology service");
    setselectedPhysiotherapyService(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (laboratoryOrdersApi.data && laboratoryOrdersApi.data.length) {
      setlaboratoryOrders(laboratoryOrdersApi.data);
    }
    console.log("laboratoryOrdersApi.data", laboratoryOrdersApi.data);
  }, [laboratoryOrdersApi.data]);

  useEffect(() => {
    if (updated === true) {

      getlaboratoryOrders();
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(laboratoryOrders);
  }, [laboratoryOrders]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      laboratoryOrders &&
      laboratoryOrders.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        laboratoryOrders.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(laboratoryOrders);
    }
  };

  return laboratoryOrdersApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">
   

        <RadiologyPaymentsTable
      title={"Entity Laboratory Services"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default RadiologyOrdersList;
